#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Outline's OIDC client at the IdP on nc8kg1101 (#303).
# Creates the `outline` OAuth2 provider and application in Authentik, then writes
# OIDC_CLIENT_ID and OIDC_CLIENT_SECRET into nc8kg1101/outline/outline.sops.env with
# `sops set --value-stdin`, commits and pushes. Never prints a secret.
# Re-runnable: Enter keeps a value already in the repo.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

FILE="nc8kg1101/outline/outline.sops.env"
STACK_ENV="nc8kg1101/outline/.sops.env"
NO_PUSH="${WIZARD_NO_PUSH:-}"

ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
die() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }

# current KEY: KEY's value in $FILE, or nothing while it is empty.
current() {
  sops -d --extract "[\"$1\"]" "$FILE" 2>/dev/null || true
}

# collect VAR KEY "Prompt" REGEX "expected" [visible]: Enter keeps the repo's value; checked against REGEX.
collect() {
  local var="$1" key="$2" prompt="$3" regex="$4" input="" existing
  existing=$(current "$key")
  while :; do
    if [[ -n "$existing" ]]; then
      printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
    else
      printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
    fi
    if [[ -n "${6:-}" ]]; then read -r input || [[ -n "$input" ]] || die "no input"
    else read -rs input || [[ -n "$input" ]] || die "no input"; printf '\n'; fi
    [[ -z "$input" && -n "$existing" ]] && input="$existing"
    [[ "$input" =~ $regex ]] && break
    warn "that does not look right; expected $5"
  done
  printf -v "$var" '%s' "$input"
}

# store KEY VALUE: JSON-encode VALUE and set it in $FILE. An unchanged value is left alone.
store() {
  if [[ "$(current "$1")" == "$2" ]]; then
    ok "$1 unchanged"
    return
  fi
  printf '%s' "$2" | jq -Rsc . | sops set --value-stdin "$FILE" "[\"$1\"]"
  ok "wrote $1 → $FILE"
}

cd "$(git rev-parse --show-toplevel)"

banner "nc8kg1101 outline: sign in with the IdP"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check prerequisites"
say "Checks this machine's tools and the checkout. Writes nothing yet."
for tool in git sops jq curl; do
  command -v "$tool" >/dev/null 2>&1 || die "$tool is not installed"
done
[[ -f "$FILE" ]] || die "no $FILE; check out the branch that holds the outline Stack"
sops -d "$FILE" >/dev/null || die "cannot decrypt $FILE with your sops key"
DOMAIN=$(sops -d --extract '["DOMAIN"]' "$STACK_ENV") || die "cannot read DOMAIN from $STACK_ENV"
IDP="https://idp.$DOMAIN"
OUTLINE="https://oln.$DOMAIN"
ok "your sops key decrypts the outline Stack's files"
if [[ -z "$NO_PUSH" ]]; then
  [[ -z "$(git status --porcelain)" ]] || die "the checkout has uncommitted changes"
  BRANCH=$(git branch --show-current)
  [[ -n "$BRANCH" && "$BRANCH" != "main" ]] || die "check out the outline Stack's PR branch, not main"
  git pull -q --ff-only || die "cannot fast-forward $BRANCH from origin"
  ok "on $BRANCH, up to date"
fi
say "Sign in to the IdP's admin interface as an administrator in the browser that opens next."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Check the IdP needs no Docker socket"
say "The new Stack runs authentik-worker without /var/run/docker.sock. The worker only uses it"
say "for a Docker outpost integration, which deploys outposts as containers."
open_url "$IDP/if/admin/#/outpost/integrations"
step "Applications → Outposts → Integrations: the list must have no Docker Service-Connection."
open_url "$IDP/if/admin/#/outpost/outposts"
step "Applications → Outposts: only 'authentik Embedded Outpost' should be listed."
confirm "No Docker integration and only the embedded outpost?" \
  || die "stop here and tell the lead: the worker needs the Docker socket (through docker-socket-proxy)"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Scope mapping: verified email"
say "Outline signs a user in only when the IdP says their email is verified. The IdP's default"
say "email mapping reports it unverified, so Outline gets its own mapping."
open_url "$IDP/if/admin/#/core/property-mappings"
step "Customization → Property Mappings → Create → Scope Mapping → Next."
step "Name: Outline: email (verified). Scope name: email."
step "Expression (replace the whole box):"
note '    return {"email": request.user.email, "email_verified": True}'
step "Finish. Skip this stage if the mapping already exists."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "OAuth2 provider: outline"
open_url "$IDP/if/admin/#/core/providers"
step "Applications → Providers → Create → OAuth2/OpenID Provider → Next."
step "Name: outline. Authorization flow: default-provider-authorization-implicit-consent."
step "Client type: Confidential."
step "Redirect URIs/Origins: Strict, $OUTLINE/auth/oidc.callback"
step "Signing Key: authentik Self-signed Certificate."
step "Advanced protocol settings → Scopes: keep 'openid' and 'profile', remove the default"
step "  'email' mapping and add 'Outline: email (verified)'."
step "Finish. Leave the provider page open: stage 7 copies its Client ID and Client Secret."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Application: outline"
open_url "$IDP/if/admin/#/core/applications"
step "Applications → Applications → Create."
step "Name: Outline. Slug: outline (the Stack's logout URL uses it). Provider: outline."
step "UI settings → Launch URL: $OUTLINE"
step "Optional: Policy / Group / User Bindings to limit who may sign in to Outline."
step "Create."
if curl -fsS -o /dev/null "$IDP/application/o/outline/.well-known/openid-configuration"; then
  ok "the IdP serves the outline application's OpenID configuration"
else
  warn "the IdP does not serve $IDP/application/o/outline/.well-known/openid-configuration yet"
  confirm "Continue anyway?" || die "check the application's slug and provider, then re-run"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Match Outline members to IdP users"
say "Once Outline only signs in through the IdP, it finds each member by email. A member whose"
say "email differs from their IdP user's email gets a new, empty account instead."
open_url "$OUTLINE/settings/members"
step "Note each Outline member's email."
open_url "$IDP/if/admin/#/identity/users"
step "Directory → Users: give each of those people an IdP user with exactly that email,"
step "  or change the email in Outline (Settings → Members) to match."
confirm "Does every Outline member have an IdP user with the same email?" \
  || die "match the emails first, then re-run"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Store the client credentials"
say "Back on the outline provider's page ($IDP/if/admin/#/core/providers)."
step "Copy the Client ID."
collect OIDC_CLIENT_ID OIDC_CLIENT_ID "Paste the Client ID:" '^[A-Za-z0-9]{20,}$' "20 or more letters and digits" visible
step "Copy the Client Secret (the copy button next to it)."
collect OIDC_CLIENT_SECRET OIDC_CLIENT_SECRET "Paste the Client Secret:" '^[A-Za-z0-9]{40,}$' "40 or more letters and digits"
store OIDC_CLIENT_ID "$OIDC_CLIENT_ID"
store OIDC_CLIENT_SECRET "$OIDC_CLIENT_SECRET"
if [[ -z "$NO_PUSH" ]]; then
  if git diff --quiet -- "$FILE"; then
    ok "nothing to commit"
  else
    git add "$FILE"
    git commit -q -m "outline: OIDC client for the IdP's outline application (#303)"
    git push -q
    ok "committed and pushed $FILE to $BRANCH"
  fi
fi

finish
say "Outline switches to the IdP when the outline Stack deploys (the cutover runbook)."
printf '\n'
